@php $lateDays = (int) \App\Models\Setting::get('late_shipment_days', 3); @endphp
<h2>އޯޑަރުގެ ތިޔަ ބައި</h2>
<p>ކަސްޓަމަރަކަށް އެއް ޗެކްއައުޓަކުން ގިނަ ފިހާރަތަކަކުން ތަކެތި ގަނެވޭނެ. އިރުއަލިން އޯޑަރު ބަހާލަނީ ކޮންމެ ފިހާރައަކަށް އެއް ބައި؛ ތިޔައަށް ފެންނާނީ އަދި ބަލަހައްޓާނީ ތިޔަ ތަކެތި އެކަނި، އަދި އެއްވެސް އެއްޗެއް ޕެކްކުރުމުގެ ކުރިން ކަސްޓަމަރު ކާޑުން އިރުއަލިއަށް ފައިސާ ދައްކާނެ. 24 ގަޑިއިރު ތެރޭ ފައިސާ ނުދައްކާ ކާޑު އޯޑަރުތައް އަމިއްލައަށް ކެންސަލްވެ ސްޓޮކް އަލުން ލެވޭނެ.</p>

<h2>ސްޓޭޓަސްތައް</h2>
<ol>
    <li><strong>ޕެންޑިންގ</strong> – އާ އޯޑަރެއް. ޕެކްކުރަންވީ ތަކެއްޗާއެކު އީމެއިލެއް ލިބޭނެ (<a href="{{ route('seller.settings.notifications') }}">ސެޓިންގްސް → ނޮޓިފިކޭޝަން</a> އިން ދިއްލާ ނުވަތަ ނިއްވާލެވޭނެ).</li>
    <li><strong>ޕްރޮސެސިންގ</strong> – ޕެކްކުރަން ފެށުމާއެކު އޯޑަރުގައި <em>Start preparing</em> ފިތާލާ. އޯޑަރު ޕްރޮސެސިންގއަށް ދިޔަކަން ކަސްޓަމަރަށް ފެންނާނެ.</li>
    <li><strong>ޝިޕްޑް</strong> – ޕާރުސަލް ތިޔަ އަތުން ދިއުމުން <em>Mark as sent</em> ފިތާލައި، ޓްރެކިންގ ނޯޓެއް ލިޔުއްވާ: ލޯންޗު ނުވަތަ ފްލައިޓް، ކުރިއަރު، އަދި ކަސްޓަމަރަށް ބުނެވޭނެ ރެފަރެންސެއް. އެ އޯޑަރުގެ އެހެން ފިހާރަތައް އަދިވެސް ޕެކްކުރަނީނަމަ، <em>ތިޔަ</em> ތަކެތި އަންނަނީ ކަމަށް ކަސްޓަމަރަށް އީމެއިލް ފޮނުވޭނެ.</li>
    <li><strong>ޑެލިވަރޑް</strong> – ކަސްޓަމަރަށް ލިބުމުން <em>Mark as delivered</em> ފިތާލާ. މިއިން ރިޓާން މުއްދަތު ފެށޭނެ އަދި ތިޔަ ފައިސާ ދެއްކޭ ހާލަތަށް ދާނެ.</li>
</ol>
<p>ސްޓޭޓަސް ދާނީ ކުރިއަށް އެކަނި. ކަސްޓަމަރުގެ އޯޑަރުގައި ފެންނާނީ އެންމެ ލަސް ފިހާރައިގެ ސްޓޭޓަސް. ތިޔަ ބައި އަމިއްލައަށް ކެންސަލެއް ނުކުރެވޭނެ؛ އޯޑަރު ޕެންޑިންގގައި އޮންނައިރު ކަސްޓަމަރަށް ކެންސަލްކުރެވޭނެ، އޭގެ ފަހުން މައްސަލަތައް އިރުއަލިން ބަލަހައްޓާނީ ރިޓާނެއްގެ ގޮތުގައި.</p>

<h2>މުއްދަތުތައް</h2>
<ul>
    <li><strong>ފައިސާ ދެއްކިތާ {{ $lateDays }} ދުވަސް ތެރޭ</strong> ފޮނުވާ. އެއަށްވުރެ ލަހުން ފޮނުވާ ބައިތައް ތިޔަ ޕާފޯމަންސް ޞަފްޙާގައި ލަސް ކަމަށް ގުނޭނެ، އަދި އިރުއަލިން އެ ބަލާނެ.</li>
    <li>ވަގުތަށް ނުފޮނުވޭނަމަ (ސްޓޮކް ހުސްވުން، މޫސުން ގޯސްވުން)، ކަސްޓަމަރަށް އަންގައި ނުވަތަ ރިފަންޑް ދެވޭނެހެން ވަގުތުން އިރުއަލިއަށް އަންގަވާ.</li>
</ul>

<h2>ރަށްރަށަށް ޑެލިވަރީ</h2>
<ul>
    <li>ކަސްޓަމަރު ދައްކަނީ އޯޑަރަކަށް އެއް ޑެލިވަރީ ފީ، އިރުއަލިއަށް: މާލެ ސަރަހައްދަށް (މާލެ، ހުޅުމާލެ، ވިލިމާލެ) އެއް ރޭޓް އަދި އެހެން ރަށްރަށަށް އެހެން ރޭޓެއް. ތިޔައިން ވަކިން ޑެލިވަރީ ފީއެއް ނުނަގާނެ.</li>
    <li>ފޮނުވާ ގޮތް ބުނެދޭން ތިޔަ <a href="{{ route('seller.profile') }}#delivery">ޕްރޮފައިލް</a> ގެ ޑެލިވަރީ ނޯޓު ބޭނުންކުރައްވާ: ބޯޓު، ސްޕީޑް ލޯންޗު، ޑޮމެސްޓިކް ފްލައިޓް ކާގޯ ނުވަތަ މާލޭގައި ކުރިއަރު، އަދި އާންމުކޮށް ނަގާ ވަގުތު.</li>
    <li>ކަސްޓަމަރުގެ ނަމާއި ރަށާއި ފޯނު ނަންބަރު ޕާރުސަލްގައި ސާފުކޮށް ލިޔުއްވާ. ބޯޓު ފަޅުވެރިން ގުޅާނީ ޕާރުސަލްގައިވާ ނަންބަރަށް؛ އެ ނަންބަރު އޯޑަރު ޞަފްޙާގައި ހުންނާނެ.</li>
    <li>ކަނޑު ދަތުރަށް ޕެކްކުރައްވާ: ކަރުދާހާއި ފޮއްޗަށް ފެން ނުވަންނަ ކޮތަޅު، ތެޅޭ ތަކެއްޗަށް ޕެޑިންގ ލީ ފޮށި، އަދި ކާބޯތަކެއްޗަށް ބަންދުކުރި ކޮންޓެއިނަރު. ހަލާކުވާ ތަކެތި ހަފްތާއަކު އެއްފަހަރު ދާ ބޯޓަކަށް މަޑުނުކޮށް ދެން ފުރާ ދަތުރަކުން ފޮނުވާ.</li>
</ul>
